pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // The current owner (this test contract) always successfully transfers ownership.
        vm.prank(c.owner());
        try c.setOwner(newOwner) returns (bool ok) {
            assertTrue(ok && c.owner() == newOwner);
        } catch {
            assertTrue(false);
        }
    }
}
